// ARCHIVO GENERADO — no editar a mano.
// Fuente: ../runtime/nodos/normalizar-investigacion.mjs (región CODE_NODE). Regenerar: node n8n/runtime/generar-code-nodes.mjs
// Investigación: une webhook y subworkflow; rechaza campos no aceptados.

const x = $input.first().json;
const PROHIBIDOS = ['system', 'system_prompt', 'prompt', 'instrucciones_sistema',
  'telefono', 'to_number', 'destinatario', 'model', 'modelo', 'nivel', 'dictamen',
  'service_role', 'apikey', 'authorization'];
const crudo = x.body ?? x;
const presentes = PROHIBIDOS.filter((k) => crudo[k] !== undefined);
if (presentes.length > 0) {
  throw new Error(`campos no aceptados en el payload: ${presentes.join(', ')}`);
}
const corrida_id = crudo.corrida_id ?? null;
if (!corrida_id) throw new Error('corrida_id obligatorio: nunca se elige corrida por aproximación');
const cluster_id = crudo.cluster_id ?? null;
const origen = crudo.origen ?? null;
const valor = crudo.valor ?? null;
if (!cluster_id && !(origen && valor)) {
  throw new Error('se requiere cluster_id, o bien origen + valor para resolver el cluster');
}
const idempotency_key = crudo.idempotency_key ?? null;
if (!idempotency_key) throw new Error('idempotency_key obligatoria: misma clave devuelve el mismo caso');
const salida = {
  corrida_id,
  cluster_id,
  origen,
  valor_untrusted: valor,
  investigacion_id: crudo.investigacion_id ?? null,
  idempotency_key,
  entrada: x.body ? 'webhook' : 'subworkflow',
};
return [{ json: salida }];

// ARCHIVO GENERADO — no editar a mano.
// Fuente: ../runtime/nodos/evaluar-frontera.mjs (región CODE_NODE). Regenerar: node n8n/runtime/generar-code-nodes.mjs
// Investigación: tabla de despertar de 03 y frontera material (07 §2.6).

const x = $input.first().json;
const TABLA_DISPARO = {
  R: ['documental', 'financiero'],
  F: ['documental', 'temporal'],
  D: ['financiero'],
  T: ['relacional'],
  E: [],
};
const ROL_POR_FAMILIA = { D: 'documental', F: 'financiero', R: 'relacional', T: 'temporal', E: 'externo' };
const FAMILIA_POR_ROL = { documental: 'D', financiero: 'F', relacional: 'R', temporal: 'T', externo: 'E' };
const MAX_EXPANSIONES_POR_CLUSTER = 1;

const senales = Array.isArray(x.senales) ? x.senales : [];
const evaluables = new Set(x.familias_evaluables ?? ['D', 'F', 'R', 'T', 'E']);
const porId = new Map(senales.map((s) => [String(s.id), s]));
const motivos = {};
const agregar = (rol, motivo) => {
  if (!rol) return;
  const familia = FAMILIA_POR_ROL[rol];
  if (!familia || !evaluables.has(familia)) return;
  if (!motivos[rol]) motivos[rol] = [];
  motivos[rol].push(motivo);
};
for (const senal of senales) {
  if (senal.refuta === true) {
    const objetivo = (senal.refuta_senal_id !== undefined && porId.has(String(senal.refuta_senal_id)))
      ? porId.get(String(senal.refuta_senal_id)).familia
      : (senal.familia_refutada ?? null);
    if (objetivo) agregar(ROL_POR_FAMILIA[objetivo], `refuta:${senal.id}`);
    continue;
  }
  if (senal.familia === 'E') {
    const afectadas = senal.familias_afectadas ?? [...evaluables].filter((f) => f !== 'E');
    for (const f of afectadas) agregar(ROL_POR_FAMILIA[f], `E:${senal.id}`);
    continue;
  }
  for (const rol of (TABLA_DISPARO[senal.familia] ?? [])) agregar(rol, `${senal.familia}:${senal.id}`);
}
const despertados = Object.keys(motivos).sort();

// Frontera material.
const dentro = new Set(x.rfcs_cluster ?? []);
const metricas = x.metricas_frontera ?? {};
const umbral = String(x.umbral_facturacion_centavos ?? '0');
const candidatos = new Set();
for (const senal of senales) for (const rfc of (senal.frontera ?? [])) if (!dentro.has(rfc)) candidatos.add(rfc);
const relevantes = [...candidatos].filter((rfc) => {
  const m = metricas[rfc];
  if (!m) return false;
  if (m.relevante === true) return true;
  if (m.facturacion_centavos === undefined) return false;
  return BigInt(m.facturacion_centavos) > BigInt(umbral);
}).sort();
const rutaMaterial = (x.rutas_materiales_cortadas ?? []).filter((rfc) => !dentro.has(rfc)).sort();
const version_contexto = Number(x.version_contexto ?? 1);
const cuotaDisponible = Number(x.expansiones_previas ?? 0) < MAX_EXPANSIONES_POR_CLUSTER;
const cumpleUmbral = relevantes.length >= 2 || rutaMaterial.length >= 1;

let frontera;
if (!cumpleUmbral) {
  frontera = {
    expandir: false, motivo: 'frontera_no_significativa', rfcs_nuevos: [],
    version_contexto_nueva: version_contexto, pendientes: [...candidatos].sort(),
    limitaciones: candidatos.size > 0 ? [{
      codigo: 'cobertura_incompleta',
      descripcion: `La cadena continúa hacia ${candidatos.size} RFC no investigados.`,
      referencias: [],
    }] : [],
  };
} else if (!cuotaDisponible) {
  frontera = {
    expandir: false, motivo: 'cuota_expansion_agotada', rfcs_nuevos: [],
    version_contexto_nueva: version_contexto, pendientes: relevantes,
    limitaciones: [{
      codigo: 'cobertura_incompleta',
      descripcion: `Ya se usó la única expansión del cluster; la cadena continúa hacia ${relevantes.length} RFC no investigados.`,
      referencias: [],
    }],
  };
} else {
  const nuevos = [...new Set([...relevantes, ...rutaMaterial])].sort();
  frontera = {
    expandir: true,
    motivo: relevantes.length >= 2 ? 'frontera_significativa' : 'ruta_material_cortada',
    rfcs_nuevos: nuevos, version_contexto_nueva: version_contexto + 1,
    pendientes: [], limitaciones: [],
  };
}

const porExpansion = frontera.expandir ? (x.roles_por_expansion ?? []) : [];
const conjunto = [...new Set([...despertados, ...porExpansion])]
  .filter((rol) => evaluables.has(FAMILIA_POR_ROL[rol]))
  .sort();
const salida = {
  // Identidad del caso: el nodo siguiente crea tareas con ella y no debe
  // volver a resolverla (misma convención que el worker).
  caso_id: x.caso_id ?? null,
  corrida_id: x.corrida_id ?? null,
  cluster_id: x.cluster_id ?? null,
  investigacion_id: x.investigacion_id ?? null,
  despertados: conjunto,
  motivos,
  frontera,
  saltar_ronda2: conjunto.length === 0,
  version_contexto: frontera.version_contexto_nueva,
};
return [{ json: salida }];

// ARCHIVO GENERADO — no editar a mano.
// Fuente: ../runtime/auditor-final.mjs (región CODE_NODE). Regenerar: node n8n/runtime/generar-code-nodes.mjs
// Auditor Final (07). Entrada preparada por backend, nunca JSON de agente sin validar.

const x = $input.first().json;
const pistas = x.pistas ?? [];
const ev = (x.evidencia ?? []).filter(e =>
  e.valida_tecnica === true && e.refutada !== true && e.validada === true);
const permitidas = new Set(['D', 'F', 'R', 'T', 'E']);
const familias = new Set(ev.map(e => e.familia).filter(f => permitidas.has(f)));
const pendientes = x.pendientes ?? [];
const prioridades = ['evidencia_invalida', 'contradiccion',
  'defensa_no_considerada', 'cadena_incompleta', 'evidencia_insuficiente'];
const pendiente = prioridades.map(m => pendientes.find(p =>
  p.motivo === m && p.reparable === true && p.objetivo)).find(Boolean);
const puedeReintentar = Number(x.caso.n_reintentos) < 2
  && x.presupuesto.permite_reintento === true;
const rechazo = pendiente && puedeReintentar
  ? { motivo: pendiente.motivo, objetivo: pendiente.objetivo } : null;
const completo = x.cobertura_completa === true && pendientes.length === 0;
const todasRefutadas = pistas.length > 0
  && pistas.every(p => p.estado === 'refutada');
const e1def = ev.some(e => e.pista_codigo === 'E1' && e.familia === 'E'
  && e.hecho_validado?.estatus === 'definitivo'
  && e.hecho_validado?.saltos === 0);
let nivel;
if (!completo) nivel = 'no_concluyente';
else if (todasRefutadas) nivel = 'anomalia_explicada';
else if (ev.length === 0 && pistas.length === 0) nivel = 'sin_hallazgos';
else if (familias.size >= 3 || (familias.size >= 2 && e1def)) nivel = 'presuncion_alta';
else if (familias.size >= 2) nivel = 'presuncion';
else nivel = 'no_concluyente';

// monto_centavos: entero decimal resuelto desde NUMERIC de DB, no del modelo.
// El mismo CFDI citado por varias familias cuenta una vez.
const porFactura = new Map();
for (const e of ev.filter(e => e.tipo === 'cfdi')) {
  const centavos = e.hecho_validado?.monto_centavos;
  if (!/^[0-9]+$/.test(String(centavos ?? ''))) {
    throw new Error(`Monto validado ausente/inválido para ${e.ref_id}`);
  }
  const valor = BigInt(centavos);
  if (porFactura.has(e.ref_id) && porFactura.get(e.ref_id) !== valor) {
    throw new Error(`Monto inconsistente para ${e.ref_id}`);
  }
  porFactura.set(e.ref_id, valor);
}
const monto = [...porFactura.values()].reduce((s, v) => s + v, 0n);
const ordenadas = [...familias].sort();
const salida = {
  // Identidad del caso: el dictamen y el reintento la necesitan y no deben
  // volver a resolverla (misma convención de cableado que el worker).
  caso_id: x.caso_id ?? null,
  cluster_id: x.cluster_id ?? null,
  corrida_id: x.corrida_id ?? null,
  investigacion_id: x.investigacion_id ?? null,
  rechazo,
  nivel,
  familias: ordenadas,
  monto_en_riesgo_centavos: monto.toString(),
  regla: `${ordenadas.length} familia(s) sustentadas: ${ordenadas.join(', ')} → ${nivel}`,
  limitaciones: pendientes.map(p => p.motivo),
};
return [{ json: salida }];
